
<script setup lang="ts">
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { User, Lock, Phone, FirstAidKit, Van } from '@element-plus/icons-vue'
import { authApi } from '@/api'
const router=useRouter();const loading=ref(false);const form=reactive({username:'',nickname:'',phone:'',password:'',confirmPassword:''})
const submit=async()=>{if(!form.username||!form.nickname||!form.password)return ElMessage.warning('请完整填写必填信息');if(form.password.length<6)return ElMessage.warning('密码至少为 6 位');if(form.password!==form.confirmPassword)return ElMessage.warning('两次密码输入不一致');loading.value=true;try{await authApi.register(form);ElMessage.success('注册成功，请登录');router.push('/login')}finally{loading.value=false}}
</script>
<template><div class="auth-page"><div class="auth-visual"><div class="auth-brand"><span class="brand-mark"><FirstAidKit/></span><div><b>速安药房</b><small>PHARMACY DELIVERY</small></div></div><div class="visual-copy"><span class="visual-pill">新用户注册</span><h1>健康服务<br/><i>即刻开始</i></h1><p>注册成为普通用户，体验在线选药、<br/>购物车结算与即时配送流程。</p></div><div class="route-line"><span class="route-node n1"><FirstAidKit/></span><span class="route-node n2"><Van/></span><b></b></div></div><div class="auth-form-wrap"><div class="auth-card"><span class="eyebrow">CREATE ACCOUNT</span><h2>创建账号</h2><p class="auth-sub">注册后即可开始浏览和下单</p><el-form @submit.prevent="submit"><el-form-item><el-input v-model="form.username" size="large" placeholder="账号：4~32 位字母、数字或下划线" :prefix-icon="User"/></el-form-item><el-form-item><el-input v-model="form.nickname" size="large" placeholder="昵称" :prefix-icon="User"/></el-form-item><el-form-item><el-input v-model="form.phone" size="large" placeholder="手机号（选填）" :prefix-icon="Phone"/></el-form-item><el-form-item><el-input v-model="form.password" size="large" type="password" show-password placeholder="设置 6~32 位密码" :prefix-icon="Lock"/></el-form-item><el-form-item><el-input v-model="form.confirmPassword" size="large" type="password" show-password placeholder="确认密码" :prefix-icon="Lock" @keyup.enter="submit"/></el-form-item><el-button class="auth-submit" type="primary" size="large" :loading="loading" @click="submit">完成注册</el-button></el-form><p class="auth-switch">已有账号？<a @click="router.push('/login')">去登录</a></p></div></div></div></template>
<style scoped>
