x){.auth-page{grid-template-columns:1fr}.auth-visual{min-height:250px;padding:28px}.visual-copy{margin-top:32px}.visual-copy h1{font-size:38px;margin:15px 0}.route-line{display:none}.auth-form-wrap{padding:35px 24px}}
